lcalinité du substratFilm résistant aux intempéries et aux UVHomogénéisation facile à l'ouverture et application aisée"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/peinture-antihumidite-blanc-satine-14l') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('56b1be34-c9ea-582d-bbd2-4c7308f962ac'::uuid, 'a4a38245-1562-5e3b-8e20-be8fdd00b130'::uuid, 'Revêtement époxy alimentaire certifié po', 'Revêtement époxy alimentaire certifié pour l''eau potable blanc 20kg', 'Interior coatings', NULL, NULL, 3000.0, 'MAD', 'Kilogramme', '20 Kilogramme', 'https://lechantier.ma/uploads/media/e39ee3ad8a9d.webp', $j$["https://lechantier.ma/uploads/media/e39ee3ad8a9d.webp", "https://lechantier.ma/uploads/media/da55e563dda8.webp", "https://lechantier.ma/uploads/media/47da743cf633.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-interieur/revetement-epoxy-alimentaire-certifie-po", "category_fr": "Revêtement mural", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Peinture alimentaire époxy bicomposante 100% solide avec des tests de migration globaux et spécifiques. Convient pour la doublure intérieure des réservoirs, tuyaux ou réservoirs d'eau potable, des planchers et des murs situés dans des environnements alimentaires et sanitaires. Il supporte en permanence des températures de 50°C et des pics allant jusqu’à 60°C sans altérer aucune de ses propriétés.", "technical_specifications_original": "• Peinture alimentaire époxy bicomposante 100% solide avec des tests de migration globaux et spécifiques. Convient pour la doublure intérieure des réservoirs, tuyaux ou réservoirs d'eau potable, des planchers et des murs situés dans des environnements alimentaires et sanitaires. Il supporte en permanence des températures de 50°C et des pics allant jusqu’à 60°C sans altérer aucune de ses propriétés.", "specs": "• Peinture alimentaire époxy bicomposante 100% solide avec des tests de migration globaux et spécifiques. Convient pour la doublure intérieure des réservoirs, tuyaux ou réservoirs d'eau potable, des planchers et des murs situés dans des environnements alimentaires et sanitaires. Il supporte en permanence des températures de 50°C et des pics allant jusqu’à 60°C sans altérer aucune de ses propriétés."}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-interieur/revetement-epoxy-alimentaire-certifie-po') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
