INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('79355e23-b8cc-5882-b156-1074bcdc2a62'::uuid, '03a10c1f-c4bb-5b9d-98c4-5b83f6367576'::uuid, 'Cimacoll', 'Mortier-colle professionnel prêt à l''emploi 🔹 Utilisation : Pose de carrelage, marbre, pierres naturelles et céramique', 'Other', NULL, NULL, 30.0, 'MAD', 'm²', '25 kg', 'https://lechantier.ma/uploads/media/e51337dd8c68.webp', $j$["https://lechantier.ma/uploads/media/e51337dd8c68.webp", "https://lechantier.ma/uploads/media/53dd6b260aab.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-mur-autres/cimacoll", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Aspect Poudre homogène grise ou blancheComposition Ciment, charges minérales, résines, additifsGranulométrie < 0,5 mmProportion d’eau de gâchage 5 à 6 litres / sac de 25 kgTemps d’utilisation du mélange 3 à 4 heures (à 20°C)Temps ouvert ≥ 20 minutesTemps d’ajustabilité Environ 15 minutesDélai de mise en service Circulation légère après 24 hÉpaisseur d’application 3 à 10 mm selon le supportRendement moyen 4 à 5 kg/m² (selon taille du carreau et support)Adhérence initiale (norme EN 12004) ≥ 0.5 MPa (C1) ou ≥ 1.0 MPa (C2, selon version)Résistance à l’eau & au gel Très bonne (après durcissement complet)", "technical_specifications_original": "• Aspect Poudre homogène grise ou blancheComposition Ciment, charges minérales, résines, additifsGranulométrie < 0,5 mmProportion d’eau de gâchage 5 à 6 litres / sac de 25 kgTemps d’utilisation du mélange 3 à 4 heures (à 20°C)Temps ouvert ≥ 20 minutesTemps d’ajustabilité Environ 15 minutesDélai de mise en service Circulation légère après 24 hÉpaisseur d’application 3 à 10 mm selon le supportRendement moyen 4 à 5 kg/m² (selon taille du carreau et support)Adhérence initiale (norme EN 12004) ≥ 0.5 MPa (C1) ou ≥ 1.0 MPa (C2, selon version)Résistance à l’eau & au gel Très bonne (après durcissement complet)", "specs": "• Aspect Poudre homogène grise ou blancheComposition Ciment, charges minérales, résines, additifsGranulométrie < 0,5 mmProportion d’eau de gâchage 5 à 6 litres / sac de 25 kgTemps d’utilisation du mélange 3 à 4 heures (à 20°C)Temps ouvert ≥ 20 minutesTemps d’ajustabilité Environ 15 minutesDélai de mise en service Circulation légère après 24 hÉpaisseur d’application 3 à 10 mm selon le supportRendement moyen 4 à 5 kg/m² (selon taille du carreau et support)Adhérence initiale (norme EN 12004) ≥ 0.5 MPa (C1) ou ≥ 1.0 MPa (C2, selon version)Résistance à l’eau & au gel Très bonne (après durcissement complet)"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-mur-autres/cimacoll') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('3bd12a82-0171-5257-89a9-b3e03d796a13'::uuid, 'b10c8182-7d17-5d86-a346-e336a8c66383'::uuid, 'Mur végétal stabilisé sur mesure', 'Mur végétal stabilisé réalisé sur mesure par Naturel Design pour les espaces résidentiels, professionnels, hôteliers et commerciaux. Chaque composition est conçue selon les dimensions, l''ambiance et l''identité du lieu, avec un choix de mousses, lichens, feuillages et végétaux naturels stabilisés. Le végétal stabilisé permet de créer un décor naturel durable, sans arrosage, sans terre et avec très peu d''entretien.', 'Other', 'Naturel Design', NULL, 2500.0, 'MAD', 'm²', NULL, 'https://lechantier.ma/uploads/media/947ccfc9efd6.webp', $j$["https://lechantier.ma/uploads/media/947ccfc9efd6.webp", "https://lechantier.ma/uploads/media/6890ce2299bd.webp", "https://lechantier.ma/uploads/media/136d6b2bd4a2.webp", "https://lechantier.ma/uploads/media/355f7c97fb07.webp", "https://lechantier.ma/uploads/media/475da8772e19.webp", "https://lechantier.ma/uploads/media/99ed2052e6eb.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-mur-autres/mur-vegetal-stabilise-sur-mesure", "category_fr": "Matériaux de construction", "supplier_matching_status": "partially_matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-mur-autres/mur-vegetal-stabilise-sur-mesure') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('514320de-c954-5eb3-92e7-7c2f2c1bde04'::uuid, '642ccd06-83a9-54f6-9f51-f7673ead72dd'::uuid, 'Chibourd pvc', 'Le Chibourd est un panneau décoratif en PVC, conçu pour l''habillage et la finition des murs intérieurs. Grâce à sa simplicité, sa légèreté et la diversité de ses finitions, il permet de transformer rapidement un espace tout en apportant une touche moderne, élégante et chaleureuse.', 'Wall coverings', 'Panneaux mural', NULL, 650.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/cf6a5f193c75.webp', $j$["https://lechantier.ma/uploads/media/cf6a5f193c75.webp", "https://lechantier.ma/uploads/media/f776191d9376.webp", "https://lechantier.ma/uploads/media/3f38e7f67778.webp", "https://lechantier.ma/uploads/media/fd45d930c930.webp", "https://lechantier.ma/uploads/media/77bec22c8fb2.webp", "https://lechantier.ma/uploads/media/097e84ca116a.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-mur/chibourd-pvc", "category_fr": "Wall coverings", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Matière : PVC\n• Type : panneau décoratif pour habillage mural\n• Dimensions : 122 × 280 cm\n• Épaisseur : 5 mm\n• Surface par panneau : 3,416 m²\n• Finitions : effet bois, uni et effet tissu selon les modèles", "technical_specifications_original": "• Matière : PVC\n• Type : panneau décoratif pour habillage mural\n• Dimensions : 122 × 280 cm\n• Épaisseur : 5 mm\n• Surface par panneau : 3,416 m²\n• Finitions : effet bois, uni et effet tissu selon les modèles", "specs": "• Matière : PVC\n• Type : panneau décoratif pour habillage mural\n• Dimensions : 122 × 280 cm\n• Épaisseur : 5 mm\n• Surface par panneau : 3,416 m²\n• Finitions : effet bois, uni et effet tissu selon les modèles"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-mur/chibourd-pvc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('de0a0944-946e-5872-8bd6-f8371d73cf65'::uuid, '642ccd06-83a9-54f6-9f51-f7673ead72dd'::uuid, 'Panneau effet pierre', 'Le panneau effet pierre est une solution moderne d''habillage mural qui reproduit avec réalisme l''aspect et les motifs de la pierre naturelle. Il permet de créer des murs élégants et contemporains tout en offrant une alternative pratique aux revêtements en pierre traditionnelle.', 'Wall coverings', 'Panneaux mural', NULL, 800.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/a502e93b22a5.webp', $j$["https://lechantier.ma/uploads/media/a502e93b22a5.webp", "https://lechantier.ma/uploads/media/6253c1d097a6.webp", "https://lechantier.ma/uploads/media/6b3228f0cddb.webp", "https://lechantier.ma/uploads/media/298163271a90.webp", "https://lechantier.ma/uploads/media/bac565372feb.webp", "https://lechantier.ma/uploads/media/83ab18200c27.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-mur/panneau-effet-pierre", "category_fr": "Wall coverings", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Type : panneau décoratif mural effet pierre , Format : 60 x 290cm / 120 x 290 cm, installation : pose pratique et adaptée aux projets de rénovation et de décoration , Entretien : nettoyage et entretien facile", "technical_specifications_original": "• Type : panneau décoratif mural effet pierre , Format : 60 x 290cm / 120 x 290 cm, installation : pose pratique et adaptée aux projets de rénovation et de décoration , Entretien : nettoyage et entretien facile", "specs": "• Type : panneau décoratif mural effet pierre , Format : 60 x 290cm / 120 x 290 cm, installation : pose pratique et adaptée aux projets de rénovation et de décoration , Entretien : nettoyage et entretien facile"}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-mur/panneau-effet-pierre') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0087e66c-172e-5086-95dd-e670f7053d0b'::uuid, '642ccd06-83a9-54f6-9f51-f7673ead72dd'::uuid, 'Parquet SPC', 'Le parquet SPC (Stone Plastic Composite) est un revêtement de sol innovant composé d''un mélange de poudre de pierre et de polymères. cette structure lui confère la résistance d''eau', 'PVC flooring', NULL, NULL, 280.0, 'MAD', 'm²', '2 Mètre', 'https://lechantier.ma/uploads/media/4226207c59dc.webp', $j$["https://lechantier.ma/uploads/media/4226207c59dc.webp", "https://lechantier.ma/uploads/media/42d25f92c43e.webp", "https://lechantier.ma/uploads/media/e8e8a0c06abc.webp", "https://lechantier.ma/uploads/media/4946d7a53d58.webp", "https://lechantier.ma/uploads/media/423c7cbd8d33.webp", "https://lechantier.ma/uploads/media/76839f94b897.webp"]$j$::jsonb, $j$["Tanger"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/revetement-pvc/parquet-spc", "category_fr": "PVC flooring", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-pvc/parquet-spc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
