t du pot décoré\"", "specs": "• \"Pots en fête : l’art de jardiner avec style\"\"Des pots qui ont du cachet !\"\"Personnalise ton pot : du jardin à l’œuvre d’art\"\"Les petits pots font les grands jardins\"\"Un brin de verdure, un soupçon de déco\"\"Pots déco : quand créativité rime avec jardinage\"\"Jardin d’artiste : les pots deviennent tableaux\"\"DIY jardin : donne vie à tes pots !\"\"Des pots et des idées\"\"Colorer la nature : l’art du pot décoré\""}$j$::jsonb, 'https://lechantier.ma/en/produits/revetement-sol-autres/la-decoration-de-pots-de-jardinage') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
