INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('8df0629b-92d2-5dc0-82b2-080c5a96f1ec'::uuid, '54952528-52b6-5e6f-aba7-57fde75a319a'::uuid, 'RENOVATION D''APPARTEMENT CLE EN MAINS', 'Que ce soit pour moderniser une pièce, refaire vos sols, peaufiner vos finitions ou transformer entièrement votre espace de vie, notre équipe vous accompagne de A à Z avec un savoir-faire rigoureux et soigné. 🛠️🏡 ​🎁 Offre spéciale en ce moment : Pour toute validation de projet de rénovation ce mois-ci, l''étude et les conseils d''agencement 3D offerts ​Ce que nous vous garantissons : ✔️ Un travail soigné et des matériaux de qualité ✔️ Le respect des délais convenus ✔️ Un accompagnement personnalisé du début à la fin du chantier', 'Bathroom & sanitary ware', NULL, NULL, 70000.0, 'MAD', 'unité', NULL, 'https://lechantier.ma/uploads/pro/cmvhe7o5s01e1j02w5y6zpssf/logo-1792624656368-cd16a5d92e96.webp', $j$["https://lechantier.ma/uploads/pro/cmvhe7o5s01e1j02w5y6zpssf/logo-1792624656368-cd16a5d92e96.webp", "https://lechantier.ma/uploads/media/1edf21891466.webp", "https://lechantier.ma/uploads/media/a54a2cbdb303.webp", "https://lechantier.ma/uploads/media/e7936c4cff36.webp", "https://lechantier.ma/uploads/media/9df65bbb0a2f.webp", "https://lechantier.ma/uploads/media/1467080a9d8b.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/salle-de-bain-sanitaire/renovation-totale-des-appartements", "category_fr": "Bathroom & sanitary ware", "supplier_matching_status": "matched", "technical_specifications_detailed": null, "technical_specifications_original": null, "specs": null}$j$::jsonb, 'https://lechantier.ma/en/produits/salle-de-bain-sanitaire/renovation-totale-des-appartements') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand 