INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2ac92a29-2178-5fdb-b142-dc72d1903197'::uuid, '2fcdd72f-a8f8-53c7-99e7-9b753719cae9'::uuid, 'Poignee intellegent', 'La poignée intelligente est une innovation moderne qui combine design élégant, technologie avancée et fonctionnalité pratique. Conçue pour offrir un accès sécurisé et simplifié', 'Security', NULL, NULL, 2350.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/dc67f7946168.webp', $j$["https://lechantier.ma/uploads/media/dc67f7946168.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/securite/poignee-intellegent", "category_fr": "Security", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔐 Système de verrouillage électronique avec ouverture par empreinte digitale, code, carte RFID ou application mobile.⚙️ Mécanisme silencieux et fluide, garantissant une utilisation confortable au quotidien.🔋 Alimentation par batterie longue durée, avec alerte en cas de faible charge.📱 Connectivité intelligente (Bluetooth ou Wi-Fi) pour contrôle à distance et gestion des accès.🪶 Design ergonomique et moderne, disponible en plusieurs finitions (inox, noir mat, aluminium brossé, etc.).", "technical_specifications_original": "• 🔐 Système de verrouillage électronique avec ouverture par empreinte digitale, code, carte RFID ou application mobile.⚙️ Mécanisme silencieux et fluide, garantissant une utilisation confortable au quotidien.🔋 Alimentation par batterie longue durée, avec alerte en cas de faible charge.📱 Connectivité intelligente (Bluetooth ou Wi-Fi) pour contrôle à distance et gestion des accès.🪶 Design ergonomique et moderne, disponible en plusieurs finitions (inox, noir mat, aluminium brossé, etc.).", "specs": "• 🔐 Système de verrouillage électronique avec ouverture par empreinte digitale, code, carte RFID ou application mobile.⚙️ Mécanisme silencieux et fluide, garantissant une utilisation confortable au quotidien.🔋 Alimentation par batterie longue durée, avec alerte en cas de faible charge.📱 Connectivité intelligente (Bluetooth ou Wi-Fi) pour contrôle à distance et gestion des accès.🪶 Design ergonomique et moderne, disponible en plusieurs finitions (inox, noir mat, aluminium brossé, etc.)."}$j$::jsonb, 'https://lechantier.ma/en/produits/securite/poignee-intellegent') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('513db72d-bec0-5a3c-b693-83e42daa746c'::uuid, '4b0bca9a-90e3-51c9-bd98-70b85cf7293d'::uuid, 'Porte Coup-Feu', 'Nous vous invitons à découvrir nos portes coupe-feu, conçues pour répondre aux normes de sécurité les plus strictes. Elles offrent une résistance au feu allant jusqu''à 120 minutes', 'Security', NULL, NULL, 2200.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/cd3bc81f66dd.webp', $j$["https://lechantier.ma/uploads/media/cd3bc81f66dd.webp", "https://lechantier.ma/uploads/media/53c82241a0d4.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/securite/porte-coup-feu", "category_fr": "Security", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Conception et Matériaux de Haute QualitéVantail & Huisserie : Fabrication robuste en tôle galvanisée pour une durabilité maximale.Finition : Peinture époxy blanche RAL 9010 de série.Isolation Thermique : Isolation haute performance grâce à la laine de roche (165 kg/m³) et à la colle minérale.Sécurité Optimale : Équipée d'un joint intumescent à haute dilatation (positionné entre le vantail et la baie) pour une étanchéité parfaite en cas d'incendie.Équipements Fournis (Prête à l'installation)La porte est livrée assemblée et prête à être posée, incluant :Serrure coupe-feu certifiée CE.Paumelles certifiées CE (disponibles avec ou sans ressorts).Jeu de poignée coupe-feu et cylindre.6 pattes à scellement pour une fixation solide.Résistance et HomologationRésistance au Feu : Disponible en modèles offrant une résistance au feu de 60, 90 ou 120 minutes (selon le modèle sélectionné).Garantie & Conformité : Nos portes sont homologuées et garanties par des essais réalisés dans des laboratoires autorisés, assurant le respect des normes en vigueur.Dimensions et DisponibilitéModèles : Disponible en dimensions standards pour les versions 1 vantail et 2 vantaux.Sur Mesure : Les dimensions spéciales sont disponibles sur commande.", "technical_specifications_original": "• Conception et Matériaux de Haute QualitéVantail & Huisserie : Fabrication robuste en tôle galvanisée pour une durabilité maximale.Finition : Peinture époxy blanche RAL 9010 de série.Isolation Thermique : Isolation haute performance grâce à la laine de roche (165 kg/m³) et à la colle minérale.Sécurité Optimale : Équipée d'un joint intumescent à haute dilatation (positionné entre le vantail et la baie) pour une étanchéité parfaite en cas d'incendie.Équipements Fournis (Prête à l'installation)La porte est livrée assemblée et prête à être posée, incluant :Serrure coupe-feu certifiée CE.Paumelles certifiées CE (disponibles avec ou sans ressorts).Jeu de poignée coupe-feu et cylindre.6 pattes à scellement pour une fixation solide.Résistance et HomologationRésistance au Feu : Disponible en modèles offrant une résistance au feu de 60, 90 ou 120 minutes (selon le modèle sélectionné).Garantie & Conformité : Nos portes sont homologuées et garanties par des essais réalisés dans des laboratoires autorisés, assurant le respect des normes en vigueur.Dimensions et DisponibilitéModèles : Disponible en dimensions standards pour les versions 1 vantail et 2 vantaux.Sur Mesure : Les dimensions spéciales sont disponibles sur commande.", "specs": "• Conception et Matériaux de Haute QualitéVantail & Huisserie : Fabrication robuste en tôle galvanisée pour une durabilité maximale.Finition : Peinture époxy blanche RAL 9010 de série.Isolation Thermique : Isolation haute performance grâce à la laine de roche (165 kg/m³) et à la colle minérale.Sécurité Optimale : Équipée d'un joint intumescent à haute dilatation (positionné entre le vantail et la baie) pour une étanchéité parfaite en cas d'incendie.Équipements Fournis (Prête à l'installation)La porte est livrée assemblée et prête à être posée, incluant :Serrure coupe-feu certifiée CE.Paumelles certifiées CE (disponibles avec ou sans ressorts).Jeu de poignée coupe-feu et cylindre.6 pattes à scellement pour une fixation solide.Résistance et HomologationRésistance au Feu : Disponible en modèles offrant une résistance au feu de 60, 90 ou 120 minutes (selon le modèle sélectionné).Garantie & Conformité : Nos portes sont homologuées et garanties par des essais réalisés dans des laboratoires autorisés, assurant le respect des normes en vigueur.Dimensions et DisponibilitéModèles : Disponible en dimensions standards pour les versions 1 vantail et 2 vantaux.Sur Mesure : Les dimensions spéciales sont disponibles sur commande."}$j$::jsonb, 'https://lechantier.ma/en/produits/securite/porte-coup-feu') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
