INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('79a37506-da75-5773-8358-9f6cfcc19381'::uuid, '12cb9e66-efe1-582c-b820-841228d33eb1'::uuid, 'Les tuyaux en polyéthylène (PE)', 'Les tuyaux en polyéthylène (PE) sont des conduites souples ou semi-rigides utilisées principalement pour l''irrigation agricole,', 'Pipes', NULL, NULL, 500.0, 'MAD', 'm²', '200 mètres', 'https://lechantier.ma/uploads/media/4a45d0b1d052.webp', $j$["https://lechantier.ma/uploads/media/4a45d0b1d052.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/tuyau/les-tuyaux-en-polyethylene-pe", "category_fr": "Pipes", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Voici un paragraphe rédigé à partir des caractéristiques techniques des tuyaux en polyéthylène :Les tuyaux en polyéthylène sont fabriqués à partir de polyéthylène basse densité (PEBD) ou haute densité (PEHD), selon les besoins en souplesse et en résistance à la pression. Ils sont disponibles dans une large gamme de diamètres extérieurs standards, allant de 16 mm à 63 mm, ce qui permet de les adapter à différents types de réseaux d'irrigation ou d'adduction d’eau. Ils supportent des pressions nominales (PN) variables, généralement de PN4 à PN16, en fonction de l’application (basse ou haute pression). Ces tuyaux sont conçus pour fonctionner dans une plage de température de service allant de -10°C à +60°C, ce qui les rend adaptés à une utilisation en extérieur, même en conditions climatiques variées. Ils sont commercialisés sous forme de rouleaux de 25, 50, 100 ou 200 mètres, ou en barres droites, selon les exigences du chantier ou de l’installation.", "technical_specifications_original": "• Voici un paragraphe rédigé à partir des caractéristiques techniques des tuyaux en polyéthylène :Les tuyaux en polyéthylène sont fabriqués à partir de polyéthylène basse densité (PEBD) ou haute densité (PEHD), selon les besoins en souplesse et en résistance à la pression. Ils sont disponibles dans une large gamme de diamètres extérieurs standards, allant de 16 mm à 63 mm, ce qui permet de les adapter à différents types de réseaux d'irrigation ou d'adduction d’eau. Ils supportent des pressions nominales (PN) variables, généralement de PN4 à PN16, en fonction de l’application (basse ou haute pression). Ces tuyaux sont conçus pour fonctionner dans une plage de température de service allant de -10°C à +60°C, ce qui les rend adaptés à une utilisation en extérieur, même en conditions climatiques variées. Ils sont commercialisés sous forme de rouleaux de 25, 50, 100 ou 200 mètres, ou en barres droites, selon les exigences du chantier ou de l’installation.", "specs": "• Voici un paragraphe rédigé à partir des caractéristiques techniques des tuyaux en polyéthylène :Les tuyaux en polyéthylène sont fabriqués à partir de polyéthylène basse densité (PEBD) ou haute densité (PEHD), selon les besoins en souplesse et en résistance à la pression. Ils sont disponibles dans une large gamme de diamètres extérieurs standards, allant de 16 mm à 63 mm, ce qui permet de les adapter à différents types de réseaux d'irrigation ou d'adduction d’eau. Ils supportent des pressions nominales (PN) variables, généralement de PN4 à PN16, en fonction de l’application (basse ou haute pression). Ces tuyaux sont conçus pour fonctionner dans une plage de température de service allant de -10°C à +60°C, ce qui les rend adaptés à une utilisation en extérieur, même en conditions climatiques variées. Ils sont commercialisés sous forme de rouleaux de 25, 50, 100 ou 200 mètres, ou en barres droites, selon les exigences du chantier ou de l’installation."}$j$::jsonb, 'https://lechantier.ma/en/produits/tuyau/les-tuyaux-en-polyethylene-pe') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
