INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('64949eff-470a-520b-86e9-ada02c1d6a1d'::uuid, '34ca4eb1-299b-5ec1-8011-bd4d994972f8'::uuid, 'Casquette de Sécurité Antichoc', 'Casquette de sécurité légère avec coque intérieure rigide pour protéger contre les chocs légers. Confortable, réglable et disponible en plusieurs coloris. /// PRIX SELON MODELE ///', 'Workwear', NULL, NULL, 70.0, 'MAD', 'm²', '5 Lot', 'https://lechantier.ma/uploads/media/46dbd046721f.webp', $j$["https://lechantier.ma/uploads/media/46dbd046721f.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/vetements-de-travail/casquette-de-securite-antichoc", "category_fr": "Workwear", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Modèle : Casquette de sécurité antichocCoque intérieure : Coque rigide en ABS (antichoc)Tissu extérieur : Polyester ou coton renforcéColoris disponibles : Orange, Noir, Bleu, GrisBande réfléchissante : Présente sur la visière (selon modèle)Tour de tête : Réglable par bande velcro à l’arrièreNorme : Conforme à la norme EN 812 (protection contre les chocs légers)Utilisation recommandée : Industrie légère, logistique, maintenance, entrepôts, travaux en milieu urbain", "technical_specifications_original": "• Modèle : Casquette de sécurité antichocCoque intérieure : Coque rigide en ABS (antichoc)Tissu extérieur : Polyester ou coton renforcéColoris disponibles : Orange, Noir, Bleu, GrisBande réfléchissante : Présente sur la visière (selon modèle)Tour de tête : Réglable par bande velcro à l’arrièreNorme : Conforme à la norme EN 812 (protection contre les chocs légers)Utilisation recommandée : Industrie légère, logistique, maintenance, entrepôts, travaux en milieu urbain", "specs": "• Modèle : Casquette de sécurité antichocCoque intérieure : Coque rigide en ABS (antichoc)Tissu extérieur : Polyester ou coton renforcéColoris disponibles : Orange, Noir, Bleu, GrisBande réfléchissante : Présente sur la visière (selon modèle)Tour de tête : Réglable par bande velcro à l’arrièreNorme : Conforme à la norme EN 812 (protection contre les chocs légers)Utilisation recommandée : Industrie légère, logistique, maintenance, entrepôts, travaux en milieu urbain"}$j$::jsonb, 'https://lechantier.ma/en/produits/vetements-de-travail/casquette-de-securite-antichoc') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('d7458301-f4bc-5d50-b17a-927ff87601f6'::uuid, '34ca4eb1-299b-5ec1-8011-bd4d994972f8'::uuid, 'Combinaison Bicolore Haute Visibilité', 'Conçue pour les environnements industriels, cette combinaison allie confort, résistance et visibilité. Elle est idéale pour les travaux en extérieur ou en atelier.', 'Workwear', NULL, NULL, 200.0, 'MAD', 'Lot', '5 Lot', 'https://lechantier.ma/uploads/media/b1e2e9931311.webp', $j$["https://lechantier.ma/uploads/media/b1e2e9931311.webp", "https://lechantier.ma/uploads/media/4e63b7409c10.webp", "https://lechantier.ma/uploads/media/0bd284959a50.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/vetements-de-travail/combinaison-bicolore-haute-visibilite", "category_fr": "Workwear", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Matière : Coton / Polyester haute résistanceFermeture : Zip frontal avec patte de protectionBandes réfléchissantes : Standard, disposées sur le torse et les jambesDétails : Poches poitrine avec rabats, taille élastiquéeColoris disponibles : Rouge/Marine, Jaune/Marine, Bleu/Marine, Orange/MarineTailles : Du S au XXL", "technical_specifications_original": "• Matière : Coton / Polyester haute résistanceFermeture : Zip frontal avec patte de protectionBandes réfléchissantes : Standard, disposées sur le torse et les jambesDétails : Poches poitrine avec rabats, taille élastiquéeColoris disponibles : Rouge/Marine, Jaune/Marine, Bleu/Marine, Orange/MarineTailles : Du S au XXL", "specs": "• Matière : Coton / Polyester haute résistanceFermeture : Zip frontal avec patte de protectionBandes réfléchissantes : Standard, disposées sur le torse et les jambesDétails : Poches poitrine avec rabats, taille élastiquéeColoris disponibles : Rouge/Marine, Jaune/Marine, Bleu/Marine, Orange/MarineTailles : Du S au XXL"}$j$::jsonb, 'https://lechantier.ma/en/produits/vetements-de-travail/combinaison-bicolore-haute-visibilite') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
