INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('cba33b2e-cfd0-54c5-bc97-59db65795877'::uuid, '34ca4eb1-299b-5ec1-8011-bd4d994972f8'::uuid, 'Gilet avec poche 3M', 'Gilet de sécurité haute visibilité 3M avec bandes réfléchissantes, fermeture zippée et poches pratiques. Léger, confortable et idéal pour le travail en extérieur.', 'Workwear', NULL, NULL, 125.0, 'MAD', 'Lot', '10 Lot', 'https://lechantier.ma/uploads/media/52d93f6ed7ea.webp', $j$["https://lechantier.ma/uploads/media/52d93f6ed7ea.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/vetements-de-travail/gilet-avec-poche-3m", "category_fr": "Workwear", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Bandes réfléchissantes 3M haute visibilité, fermeture zippée frontale, poche poitrine avec rabat, tissu léger et respirant en maille, col montant, coloris jaune fluorescent.", "technical_specifications_original": "• Bandes réfléchissantes 3M haute visibilité, fermeture zippée frontale, poche poitrine avec rabat, tissu léger et respirant en maille, col montant, coloris jaune fluorescent.", "specs": "• Bandes réfléchissantes 3M haute visibilité, fermeture zippée frontale, poche poitrine avec rabat, tissu léger et respirant en maille, col montant, coloris jaune fluorescent."}$j$::jsonb, 'https://lechantier.ma/en/produits/vetements-de-travail/gilet-avec-poche-3m') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source