INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('0b7209e7-1203-50ee-a5b2-5c53cd6a962b'::uuid, '41af6f1b-4eb4-5ea9-a23a-d2debdc95a12'::uuid, 'Gilet de Chantier Simple', 'Gilet fluo simple avec bandes réfléchissantes. Convient pour les chantiers, entrepôts ou toute activité nécessitant une bonne visibilité. Personnalisation offerte dès 50 pièces !', 'Workwear', NULL, NULL, 30.0, 'MAD', 'm²', '20 Pièce', 'https://lechantier.ma/uploads/media/3c86523c59df.webp', $j$["https://lechantier.ma/uploads/media/3c86523c59df.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/vetements-de-travail/gilet-de-chantier-simple", "category_fr": "Workwear", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Matière : 100 % polyesterBandes réfléchissantes 5 cmFermeture par VelcroNorme EN ISO 20471 – Classe 2Couleurs : Jaune fluo, Orange fluoTailles : M à XXL", "technical_specifications_original": "• Matière : 100 % polyesterBandes réfléchissantes 5 cmFermeture par VelcroNorme EN ISO 20471 – Classe 2Couleurs : Jaune fluo, Orange fluoTailles : M à XXL", "specs": "• Matière : 100 % polyesterBandes réfléchissantes 5 cmFermeture par VelcroNorme EN ISO 20471 – Classe 2Couleurs : Jaune fluo, Orange fluoTailles : M à XXL"}$j$::jsonb, 'https://lechantier.ma/en/produits/vetements-de-travail/gilet-de-chantier-simple') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCL