INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2693abde-b57d-52f2-aa75-2c63b0442818'::uuid, '8e0a23b9-9ab3-50ff-b553-6a8794565959'::uuid, 'Tenu de travail', 'Tenu de travail en serge avec impression logo gratuit', 'Workwear', NULL, NULL, 200.0, 'MAD', 'm²', '500 m²', 'https://lechantier.ma/uploads/media/5bc2a2ca182d.webp', $j$["https://lechantier.ma/uploads/media/5bc2a2ca182d.webp", "https://lechantier.ma/uploads/media/257e3f3711dc.webp", "https://lechantier.ma/uploads/media/6e71ebca1c4e.webp"]$j$::jsonb, $j$["Meknès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/vetements-de-travail/tenu-de-travail", "category_fr": "Workwear", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Nos tenues de travail sont conçues pour allier durabilité, confort et sécurité. Confectionnées en tissu sergé de différents grammages selon les besoins métiers, elles sont disponibles en plusieurs couleurs personnalisables. Pour une finition professionnelle, nous proposons des marquages en DTF (Direct to Film) ou en sérigraphie, permettant d'ajouter logos, noms ou visuels selon votre charte graphique. Idéales pour les environnements industriels, logistiques, ou artisanaux, nos tenues sont fabriquées avec soin pour répondre aux exigences des professionnels partout au Maroc.", "technical_specifications_original": "• Nos tenues de travail sont conçues pour allier durabilité, confort et sécurité. Confectionnées en tissu sergé de différents grammages selon les besoins métiers, elles sont disponibles en plusieurs couleurs personnalisables. Pour une finition professionnelle, nous proposons des marquages en DTF (Direct to Film) ou en sérigraphie, permettant d'ajouter logos, noms ou visuels selon votre charte graphique. Idéales pour les environnements industriels, logistiques, ou artisanaux, nos tenues sont fabriquées avec soin pour répondre aux exigences des professionnels partout au Maroc.", "specs": "• Nos tenues de travail sont conçues pour allier durabilité, confort et sécurité. Confectionnées en tissu sergé de différents grammages selon les besoins métiers, elles sont disponibles en plusieurs couleurs personnalisables. Pour une finition professionnelle, nous proposons des marquages en DTF (Direct to Film) ou en sérigraphie, permettant d'ajouter logos, noms ou visuels selon votre charte graphique. Idéales pour les environnements industriels, logistiques, ou artisanaux, nos tenues sont fabriquées avec soin pour répondre aux exigences des professionnels partout au Maroc."}$j$::jsonb, 'https://lechantier.ma/en/produits/vetements-de-travail/tenu-de-travail') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('18326376-7708-5a7e-8bf1-ed9411da1e3d'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Armoires Informatiques', 'Coffret Informatique', 'Video surveillance (CCTV)', NULL, NULL, 480.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/136ba8089094.webp', $j$["https://lechantier.ma/uploads/media/136ba8089094.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/videosurveillance/armoires-informatiques", "category_fr": "Video surveillance (CCTV)", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Les coffrets informatiques sont conçus pour optimiser la gestion des câbles et des cordons. Faciles à monter et à démonter, ils offrent une accessibilité complète par les portes, panneaux et autres ouvertures prédécoupées ainsi que par le bas. Les coffrets s’installent partout où il est important d’assurer une qualité esthétique de haut niveau.Il permet un câblage facile grâce à l’arrivée des câbles par le haut, le bas, les côtés et même l’arrière. Ses aérations disposées sur les niveaux supérieurs assurent une circulation optimale de l’air.Ce Armoire informatique accueille les différents composants de votre réseau informatique et téléphonique. C’est une solution idéale pour les entreprises disposant d’équipements informatiques restreints.", "technical_specifications_original": "• Les coffrets informatiques sont conçus pour optimiser la gestion des câbles et des cordons. Faciles à monter et à démonter, ils offrent une accessibilité complète par les portes, panneaux et autres ouvertures prédécoupées ainsi que par le bas. Les coffrets s’installent partout où il est important d’assurer une qualité esthétique de haut niveau.Il permet un câblage facile grâce à l’arrivée des câbles par le haut, le bas, les côtés et même l’arrière. Ses aérations disposées sur les niveaux supérieurs assurent une circulation optimale de l’air.Ce Armoire informatique accueille les différents composants de votre réseau informatique et téléphonique. C’est une solution idéale pour les entreprises disposant d’équipements informatiques restreints.", "specs": "• Les coffrets informatiques sont conçus pour optimiser la gestion des câbles et des cordons. Faciles à monter et à démonter, ils offrent une accessibilité complète par les portes, panneaux et autres ouvertures prédécoupées ainsi que par le bas. Les coffrets s’installent partout où il est important d’assurer une qualité esthétique de haut niveau.Il permet un câblage facile grâce à l’arrivée des câbles par le haut, le bas, les côtés et même l’arrière. Ses aérations disposées sur les niveaux supérieurs assurent une circulation optimale de l’air.Ce Armoire informatique accueille les différents composants de votre réseau informatique et téléphonique. C’est une solution idéale pour les entreprises disposant d’équipements informatiques restreints."}$j$::jsonb, 'https://lechantier.ma/en/produits/videosurveillance/armoires-informatiques') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
