INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('9e06f44c-1f12-5c01-bb40-75e122160c4b'::uuid, '5eaf47b4-1fba-5a21-b95f-425411572000'::uuid, 'Disque Dur', 'Disque dur surveillance', 'Video surveillance (CCTV)', NULL, NULL, 800.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/51e85177e66b.webp', $j$["https://lechantier.ma/uploads/media/51e85177e66b.webp"]$j$::jsonb, $j$["Marrakech"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/videosurveillance/disque-dur", "category_fr": "Video surveillance (CCTV)", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le Disque Dur 3.5″ est conçu spécifiquement pour les systèmes de vidéosurveillance haute performance. Ce disque dur de 4 To offre un stockage fiable pour les vidéosurveillance 24/7 et supporte des enregistrements haute définition de plusieurs caméras. Avec une capacité de 4 To, il est idéal pour les systèmes de vidéosurveillance nécessitant un stockage constant et une récupération rapide des données. Profitez d’une utilisation sans interruption grâce à sa robustesse et sa performance optimisée pour des enregistrements continus.Caractéristiques principales :Capacité de 4 To : Idéal pour le stockage de vidéosurveillance à long terme.Format 3.5″ : Convient aux installations avec des boîtiers de stockage standard.Conçu pour 24/7 : Fonctionnement continu pour une vidéosurveillance sans interruption.Performance stable : Assure une performance élevée et constante pour les flux vidéo en haute définition.Fiabilité et robustesse : Conçu pour des environnements de surveillance à forte charge de travail.Spécifications :Capacité : 4 ToFormat : 3.5″Compatibilité : Idéal pour les systèmes de vidéosurveillanceApplications : Surveillance continue 24/7Type : Disque dur pour vidéosurveillanceTechnologie : Optimisé pour u